//! `belsk2.lock`: the exact commit of every git dependency, so a project
//! builds the same way until `belsk2 update` is run.
//!
//! ```toml
//! # Generated by belsk2. Commit this file; do not edit it by hand.
//! version = 1
//!
//! [[package]]
//! name = "json"
//! version = "1.0.0"
//! git = "https://github.com/someone/json.belsk2"
//! reference = "tag=v1.0.0"
//! commit = "4f2a..."
//! ```

use std::path::Path;

use belsk2_syntax::Error;
use serde::{Deserialize, Serialize};

pub const LOCKFILE: &str = "belsk2.lock";

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Lockfile {
    pub version: u32,
    #[serde(default, rename = "package")]
    pub packages: Vec<LockedPackage>,
}

#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Serialize, Deserialize)]
pub struct LockedPackage {
    pub name: String,
    pub version: String,
    pub git: String,
    pub reference: String,
    pub commit: String,
}

impl Default for Lockfile {
    fn default() -> Self {
        Lockfile {
            version: 1,
            packages: Vec::new(),
        }
    }
}

impl Lockfile {
    /// Reads `belsk2.lock` from `dir`; an absent file is an empty lock.
    pub fn load(dir: &Path) -> Result<Lockfile, Error> {
        let path = dir.join(LOCKFILE);
        let Ok(text) = std::fs::read_to_string(&path) else {
            return Ok(Lockfile::default());
        };
        toml::from_str(&text).map_err(|e| {
            Error::project(format!(
                "{}: {} (delete the file to recreate it)",
                path.display(),
                e.message()
            ))
        })
    }

    pub fn save(&self, dir: &Path) -> Result<(), Error> {
        let path = dir.join(LOCKFILE);
        let body = toml::to_string(self).unwrap_or_default();
        let text =
            format!("# Generated by belsk2. Commit this file; do not edit it by hand.\n{body}");
        std::fs::write(&path, text)
            .map_err(|e| Error::io(format!("cannot write {}: {e}", path.display())))
    }

    pub fn find(&self, git: &str, reference: &str) -> Option<&LockedPackage> {
        self.packages
            .iter()
            .find(|p| p.git == git && p.reference == reference)
    }

    /// Same entries regardless of order.
    pub fn same_as(&self, other: &Lockfile) -> bool {
        let mut a = self.packages.clone();
        let mut b = other.packages.clone();
        a.sort();
        b.sort();
        a == b
    }
}
